#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Copies stdin to the clipboard (Windows clip.exe, macOS pbcopy, Linux xclip).
to_clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then pbcopy
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard
  else cat >/dev/null; return 1; fi
}

# copied "what" pipes stdin to the clipboard and tells the human.
copied() {
  if to_clipboard; then printf '  %s✓ tersalin ke clipboard:%s %s\n' "$GREEN" "$RESET" "$1"
  else warn "clipboard tidak tersedia; salin manual: $1"; fi
}

run_wizard() {

cd "$(dirname "$0")/.."   # repo root, so .env and the SQL/YAML paths resolve

TOTAL_STAGES=7

banner "Setup backend Flowku: Supabase + PowerSync"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Supabase: project ref dan publishable key"
open_url "https://supabase.com/dashboard/projects"
step "Buka project Anda (buat baru kalau belum ada)."
step "Lihat alamat di browser: supabase.com/dashboard/project/<REF>/..."
note "REF = 20 huruf kecil/angka. Boleh tempel seluruh URL, wizard akan mengambil REF-nya."
while :; do
  ask SUPABASE_REF "Project ref:"
  [[ "$SUPABASE_REF" =~ project/([a-z0-9]{20}) ]] && SUPABASE_REF="${BASH_REMATCH[1]}"
  [[ "$SUPABASE_REF" =~ ^[a-z0-9]{20}$ ]] && break
  warn "Bukan project ref yang valid (harus 20 huruf kecil/angka). Coba lagi."
done
write_env SUPABASE_REF "$SUPABASE_REF"
write_env SUPABASE_URL "https://$SUPABASE_REF.supabase.co"

open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/settings/api-keys"
step "Salin Publishable key (diawali sb_publishable_)."
note "Project lama tanpa publishable key: pakai legacy anon key (diawali eyJ)."
warn "JANGAN tempel secret key (sb_secret_ / service_role): key itu akan ikut masuk APK."
while :; do
  ask SUPABASE_PUBLISHABLE_KEY "Publishable key:"
  case "$SUPABASE_PUBLISHABLE_KEY" in
    sb_publishable_*|eyJ*) break ;;
    sb_secret_*) warn "Itu secret key. Tempel publishable key." ;;
    *) warn "Format tidak dikenali. Harus diawali sb_publishable_ (atau eyJ untuk legacy anon key)." ;;
  esac
done
write_env SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Supabase: buat tabel (migration)"
copied "isi supabase/migrations/0001_init.sql" < supabase/migrations/0001_init.sql
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/sql/new"
step "Klik area editor SQL, tekan Ctrl+V, lalu klik Run."
step "Hasil yang benar: 'Success. No rows returned'."
note "Kalau error 'already exists': migration sudah pernah dijalankan. Lanjutkan saja."
pause "Sudah sukses? Tekan Enter"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Supabase: user database untuk PowerSync"
say "PowerSync membaca perubahan data lewat user khusus 'powersync_role'."
say "Wizard membuat password acak. Password ini tidak disimpan di file mana pun."
# Hex only, so it is safe inside SQL quotes and connection URIs.
PS_DB_PASSWORD=$(openssl rand -hex 24)
cat <<SQL | copied "SQL pembuatan powersync_role (dengan password baru)"
DO \$\$ BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'powersync_role') THEN
    ALTER ROLE powersync_role WITH REPLICATION BYPASSRLS LOGIN PASSWORD '$PS_DB_PASSWORD';
  ELSE
    CREATE ROLE powersync_role WITH REPLICATION BYPASSRLS LOGIN PASSWORD '$PS_DB_PASSWORD';
  END IF;
END \$\$;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO powersync_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO powersync_role;
SQL
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/sql/new"
step "Tab SQL baru: Ctrl+V, lalu Run. Hasil: 'Success. No rows returned'."
note "Menjalankan wizard ulang akan mengganti password ini; Stage 5 lalu memakai yang baru."
pause "Sudah sukses? Tekan Enter"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Supabase: konfirmasi email (opsional)"
say "Bawaan Supabase: akun baru harus klik link di email dulu sebelum bisa login."
if confirm "Matikan konfirmasi email selama development (disarankan)?"; then
  open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/providers"
  step "Menu Authentication → Sign In / Providers → Email."
  step "Matikan 'Confirm email', lalu Save."
  note "Nyalakan lagi sebelum aplikasi dirilis ke publik."
  pause
else
  note "Dibiarkan aktif: setelah daftar di aplikasi, klik link konfirmasi di email Anda."
  pause
fi

# ── 5 ────────────────────────────────────────────────────────────────────
stage "PowerSync: hubungkan ke database Supabase"
open_url "https://dashboard.powersync.com/"
step "Buat project dan instance kalau belum ada, lalu buka instance itu."
warn "Jangan pakai tombol 'Set Up with Supabase': role dan publication sudah dibuat manual."
step "Buka view Database Connection → tab Postgres."
printf '%s' "postgresql://powersync_role@db.$SUPABASE_REF.supabase.co:5432/postgres" \
  | copied "connection URI"
step "Tempel (Ctrl+V) di field URI. Field lain terisi otomatis."
pause "Sudah ditempel? Tekan Enter untuk menyalin password"
printf '%s' "$PS_DB_PASSWORD" | copied "password powersync_role"
step "Pastikan Username = powersync_role, lalu tempel password di field Password."
step "SSL Mode biarkan verify-full."
step "Klik Test Connection. Kalau sukses, klik Save Connection."
note "Kalau gagal, salin pesan error-nya dan kirim ke Claude."
pause "Koneksi tersimpan? Tekan Enter"
printf '' | to_clipboard || true   # don't leave the DB password in the clipboard
unset PS_DB_PASSWORD

# ── 6 ────────────────────────────────────────────────────────────────────
stage "PowerSync: login pakai Supabase Auth"
step "Di instance yang sama, buka view Client Auth."
step "Centang 'Use Supabase Auth'."
step "Field 'Supabase JWT Secret (optional)' biarkan kosong (project baru memakai signing keys)."
step "Klik Save and Deploy."
pause "Sudah? Tekan Enter"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "PowerSync: Sync Streams dan URL instance"
copied "isi powersync/sync-config.yaml" < powersync/sync-config.yaml
step "Buka view Sync Streams, hapus isi editor, tekan Ctrl+V."
step "Klik Validate, lalu Deploy."
pause "Sudah ter-deploy? Tekan Enter"
step "Klik tombol Connect di bar atas, lalu salin instance URL."
while :; do
  ask POWERSYNC_URL "Instance URL:"
  [[ "$POWERSYNC_URL" =~ ^https://[^[:space:]]+$ ]] && break
  warn "URL harus diawali https://. Coba lagi."
done
write_env POWERSYNC_URL "${POWERSYNC_URL%/}"

finish
say "Jalankan aplikasi di HP:"
say "  flutter run --dart-define-from-file=.env"
printf '\n'
}

run_wizard "$@"; exit
